package com.diversestudio.openugc.storage;

import org.springframework.core.io.Resource;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;


/**
 * Common interface for file storage services.
 * Implementations can store files locally (on the server's file system) or remotely
 * (e.g. in Google Cloud Storage).
 * <p>
 * Files are addressed by a <b>storage key</b> generated by the server with
 * {@link StoredFileNames}; the key is what gets saved in the database. Methods that take a
 * {@code storedValue} also accept values written before keys existed (a full public URL or
 * a bare file name), so older rows keep working.
 */
public interface StorageService {

    /**
     * Stores a file under the given key. Never overwrites: fails if the key already exists.
     *
     * @param key         a server-generated key from {@link StoredFileNames}
     * @param file        the uploaded file
     * @param contentType the content type to store the file with (used by cloud storage)
     * @throws IOException if the file cannot be written or the key already exists
     */
    void uploadFile(String key, MultipartFile file, String contentType) throws IOException;

    /**
     * Loads a stored file as a Resource.
     *
     * @param storedValue the key (or legacy value) saved in the database
     * @throws com.diversestudio.openugc.exception.ResourceNotFoundException if the file does not exist
     * @throws IOException if the file cannot be read
     */
    Resource loadFileAsResource(String storedValue) throws IOException;

    /**
     * Deletes a stored file. Does nothing if it does not exist.
     *
     * @param storedValue the key (or legacy value) saved in the database
     * @throws IOException if deletion fails
     */
    void deleteFile(String storedValue) throws IOException;

    /**
     * Returns the public URL of a stored file, as exposed in API responses.
     *
     * @param storedValue the key (or legacy value) saved in the database; may be {@code null}
     * @return the public URL, or {@code null} if {@code storedValue} is {@code null}
     */
    String getPublicUrl(String storedValue);
}
